/* Presentation recipes use the same patient renderer and guarded clinic updates. */
(function (root) {
  const M = root.CareFlowModel;
  const patient = (title, screen, done) => ({title, screen, done: typeof done === 'string' ? c => c.u.screen === done : done});
  const clinic = (title, screen, event, done) => ({title, screen, event, done, owner:'Clinic'});
  const status = value => c => c.v?.status === value;
  const event = (title, screen, name, value) => clinic(title,screen,name,status(value));
  const booking = () => [patient('Choose the patient','C1','C2'),patient('Reason for visit and history','C2','C3'),patient('Screening before booking','C3','C6'),patient('Choose visit type','C6','C7'),...send()];
  const send = () => [patient('Choose preferred date and time','C7','C8'),patient('Review and send request','C8','C9'),patient('Open appointment details','C9','D2')];
  const confirm = () => [event('Reception confirms appointment','D2','visit:confirmed','confirmed'),clinic('Visit fee notice','D2','fee:package',c=>c.v?.feePlan==='package')];
  const login = () => [patient('Get verification code','A1',c=>c.u.otpSent),patient('Verify phone number','A1',c=>c.s.authenticated)];
  const care = screen => [clinic('Coordinator picks up',screen,'handoff:coordinating',c=>c.v?.care.tasks?.at(-1)?.status==='coordinating'),clinic('Pass details to doctor',screen,'handoff:doctor-review',c=>c.v?.care.tasks?.at(-1)?.status==='doctor-review'),clinic('Doctor reviews and replies','I5','handoff:answered',c=>c.v?.care.tasks?.at(-1)?.status==='answered')];
  const online = () => [patient('Prepare device','G1',c=>c.u.deviceReady),event('Clinic opens waiting room','G1','visit:reminder','reminder'),patient('Enter waiting room','G1',status('online-wait')),event('Doctor calls you','G2','visit:calling','calling')];
  const consult = () => [patient('Answer call','G3',status('in-consult')),event('Doctor completes and signs record','G4','visit:completed','completed'),clinic('Share after-visit information','H6','summary',c=>!!c.v?.summary)];
  const labReady = () => [clinic('Nurse receives results','H7','lab-status:lab-1:available',c=>c.l?.status==='available'),clinic('Send to doctor for review','H7','lab-status:lab-1:awaiting-review',c=>c.l?.status==='awaiting-review'),clinic('Doctor has reviewed results','H7','lab-status:lab-1:reviewed',c=>c.l?.status==='reviewed')];
  const flows = [
    {id:'F1',title:'First booking',description:'Create a profile, get screened and receive confirmation.',scenario:'new',steps:()=>[...login(),patient('Create patient profile','A3','B1'),patient('Start booking','B1','C1'),...booking(),...confirm()]},
    {id:'F2',title:'Existing profile',description:'Confirm existing details and continue booking.',scenario:'returning',steps:()=>[...login(),patient('Confirm or update existing profile','A2','B1'),patient('Book with existing profile','B1','C1'),...booking(),...confirm()]},
    {id:'F3',title:'Needs urgent help',description:'Help comes first; the clinic reviews the visit type.',scenario:'empty',variants:[['review','Still wants a visit'],['emergency','Find urgent help']],steps:variant=>variant==='emergency'?[patient('View help options','C4',c=>c.u.emergencyOpened),patient('Open contact or directions','C4',c=>c.u.emergencyAccessed)]:[patient('Read advice and request review','C4','C5'),patient('Wait for clinic to set visit type','C5','C7'),...send(),clinic('Doctor reviews suitable visit type','D2','review:onsite',status('pending')),...confirm()]},
    {id:'F4',title:'At the clinic',description:'Check in, get received and follow the visit.',scenario:'upcoming',steps:()=>[patient('Read guidance, check in','E2',status('arrived')),event('Reception checks in','E3','visit:received','received'),event('Getting ready for consultation','E3','visit:ready','ready'),event('Doctor starts consultation','E3','visit:in-consult','in-consult'),event('Sign and complete visit','E3','visit:completed','completed'),clinic('Receive after-visit information','H6','summary',c=>!!c.v?.summary)]},
    {id:'F5',title:'Tests before visit',description:'Book, send results and continue the current visit.',scenario:'pre-lab',variants:[['visit','Back to the visit'],['during','Review during visit']],steps:()=>[patient('View test order','F2','F3'),patient('Send preferred time','F3',c=>c.l?.status==='scheduled'),patient('Attach results','F4',c=>c.l?.status==='available'),event('Nurse confirms how to continue','F2','visit:confirmed','confirmed'),patient('Continue as the clinic advises','F2',c=>['D2','E3'].includes(c.u.screen))]},
    {id:'F6',title:'Cancel, reschedule or rebook',description:'Keep reasons and history; link the new visit.',scenario:'upcoming',variants:[['cancel','Cancel'],['no-show','No-show'],['reschedule','Reschedule']],steps:variant=>[...(variant==='cancel'?[patient('Cancel and give a reason','D4',status('cancelled')),patient('Choose to rebook','D2','C7')]:variant==='no-show'?[patient('View record and rebook','D2','C7')]:[patient('Choose to reschedule','D3','C7')]),...send(),...confirm()]},
    {id:'F7',title:'Online visit',description:'Prepare, answer the call and view after-visit information.',scenario:'online',steps:()=>[...online(),...consult()]},
    {id:'F8',title:'Reconnect with the clinic',description:'Call back, book another online visit or switch to in person.',scenario:'online',variants:[['callback','Wait for call back'],['online','Another online visit'],['onsite','In person']],steps:variant=>variant==='callback'?[event('Clinic arranges a call back','G5','visit:online-wait','online-wait'),event('New call from the doctor','G2','visit:calling','calling'),...consult()]:[patient('Choose new time and visit type','G5','C7'),...send(),...confirm()]},
    {id:'F9',title:'Pay visit fee',description:'Choose how to pay, track receipts and refunds.',scenario:'completed',variants:[['transfer','Bank transfer'],['counter','At the counter'],['pharmacy','Pharmacy'],['later','Pay later'],['refund','Refund'],['free','No fee']],steps:variant=>variant==='free'?[clinic('Clinic confirms no fee','H2','payment:not-required',c=>c.v?.payment.status==='not-required')]:[...(variant==='later'?[patient('Send reason and payment date','H3',c=>c.v?.payment.status==='deferred'),patient('Choose how to pay when due','H2',c=>c.v?.payment.status==='counter-pending')]:[patient(variant==='transfer'?'Report bank transfer made':'Choose where to pay',variant==='transfer'?'H4':'H2',c=>['transfer-pending','counter-pending','pharmacy-pending'].includes(c.v?.payment.status))]),clinic('Clinic confirms payment','H5','payment:paid',c=>c.v?.payment.status==='paid'),...(variant==='refund'?[clinic('Receive and check refund','H5','payment:refunding',c=>c.v?.payment.status==='refunding'),clinic('Update refund','H5','payment:refunded',c=>c.v?.payment.status==='refunded')]:[])]},
    {id:'F10',title:'Results after visit',description:'Doctor reviews, notifies and advises next steps.',scenario:'completed',variants:[['summary','Treatment information'],['more','Further tests'],['explain','Results explanation'],['callback','Could not reach']],steps:variant=>[...labReady(),...(variant==='callback'?[clinic('Record could not reach','H7','communicate:unreachable',c=>c.v?.communication.result==='unreachable')]:[]),clinic('Share results with you','H7','communicate:notified',c=>c.v?.communication.result==='notified'),...(variant==='more'?[clinic('Doctor adds an order','F1','lab:post',c=>c.v?.labs.length>1)]:variant==='explain'?[patient('Book explanation, no fee','H7','C7'),...send()]:[clinic('Share visit information','H6','summary',c=>!!c.v?.summary),clinic('Record results discussed','H7','communicate:explained',c=>c.v?.communication.explanation==='explained')])]},
    {id:'F11',title:'After-visit messages and follow-up',description:'Feedback, specialist referral and handover to the doctor.',scenario:'completed',variants:[['medicine','Prescription'],['question','Question'],['symptoms','New symptoms'],['urgent','Needs urgent help'],['tracking','Tracking'],['referral','Specialist']],steps:variant=>variant==='urgent'?[patient('Send condition needing help','I2','C4'),patient('Read guidance and contact clinic','C4','I5'),...care('I5')]:[...(variant==='referral'?[clinic('Doctor refers to specialist','I4','referral',c=>!!c.v?.care.referral)]:[]),patient('Send update to clinic',variant==='tracking'?'I3':variant==='referral'?'I4':'I2',c=>!!c.v?.care.tasks?.length),...care(variant==='tracking'?'I3':'I5')]},
    {id:'F12',title:'Follow-up',description:'Keep your profile, update your condition and start a new visit.',scenario:'completed',steps:()=>[patient('Book from previous visit','J1','C2'),patient('Update reason and history','C2','C3'),patient('Re-screen current condition','C3','C6'),patient('Choose follow-up visit type','C6','C7'),...send(),...confirm(),event('Reminder before follow-up','D2','visit:reminder','reminder')]},
  ];
  function seed(flow,variant) {
    const s=flow.scenario==='new'?M.initial():M.fixture(flow.scenario);
    let v=M.visit(s);
    if(flow.scenario==='returning')s.authenticated=false;
    if(flow.id==='F3'){
      M.beginBooking(s);Object.assign(s.draft,{reason:'I need the clinic to review my current condition.',slot:'09:00'});M.screenSafety(s,'warning');
    }
    if(flow.id==='F4')M.transition(s,v.id,'reminder','staff');
    if(flow.id==='F5')v.labs[0].returnPath=variant==='during'?'during':'visit';
    if(flow.id==='F6'&&variant==='no-show'){M.transition(s,v.id,'reminder','staff');M.transition(s,v.id,'no-show','staff');}
    if(flow.id==='F8')for(const to of ['reminder','online-wait','unreachable'])M.transition(s,v.id,to,'staff');
    return s;
  }
  root.CareFlowJourney={flows,seed};
})(window);
